#include <algorithm>
#include <array>
#include <cstdint>
#include <iostream>
#include <map>
#include <numeric>
#include <stdexcept>
#include <vector>
using namespace std;
using Rows=vector<unsigned>;
using Z=long long;
void check(bool p,const char*s){if(!p)throw runtime_error(s);}
int bit(unsigned x){return __builtin_ctz(x);}
Z hp(const Rows&r){int n=r.size(),N=1<<n;vector<Z>d(size_t(N)*n);for(int i=0;i<n;i++)d[size_t(1<<i)*n+i]=1;for(int m=1;m<N;m++)for(int i=0;i<n;i++)if(Z a=d[size_t(m)*n+i]){unsigned z=r[i]&~m;while(z){unsigned b=z&-z;z-=b;d[size_t(m|b)*n+bit(b)]+=a;}}Z ans=0;for(int i=0;i<n;i++)ans+=d[size_t(N-1)*n+i];return ans;}
Rows clone(const Rows&r,int root,int m){vector<int>old;for(int i=0;i<(int)r.size();i++)if(i!=root)old.push_back(i);int n=old.size();Rows s(n+m);for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(r[old[i]]>>old[j]&1)s[i]|=1<<j;for(int i=0;i<n;i++)for(int a=n;a<n+m;a++)if(r[old[i]]>>root&1)s[i]|=1<<a;else s[a]|=1<<i;for(int a=n;a<n+m;a++)for(int b=a+1;b<n+m;b++)s[a]|=1<<b;return s;}
array<Z,3> runs(const Rows&r){int n=r.size(),v=n-1,N=1<<v;vector<Z>d(size_t(N)*4*n);auto at=[&](int mask,int k,int last)->Z&{return d[(size_t(mask)*4+k)*n+last];};at(0,1,v)=1;for(int i=0;i<v;i++)at(1<<i,0,i)=1;for(int mask=0;mask<N;mask++)for(int k=0;k<=3;k++)for(int last=0;last<n;last++)if(Z a=at(mask,k,last)){unsigned z=r[last]&~mask&((1<<v)-1);while(z){unsigned b=z&-z;z-=b;at(mask|b,k,bit(b))+=a;}if(last!=v&&k<3&&(r[last]>>v&1))at(mask,k+1,v)+=a;}
 array<Z,3>out{};for(int k=1;k<=3;k++)for(int last=0;last<n;last++)out[k-1]+=at(N-1,k,last);return out;}
struct Pattern{unsigned code;int kind,a,b,leaves;};
map<unsigned,Pattern> patterns(int t){map<unsigned,Pattern>P;for(int c=0;c<t;c++)for(int L=1;L<(1<<t);L++)if(!(L>>c&1))for(int loop=0;loop<2;loop++){unsigned M=0;for(int j=0;j<t;j++)if(L>>j&1)M|=(1u<<(c*t+j))|(1u<<(j*t+c));if(loop)M|=1u<<(c*t+c);P.emplace(M,Pattern{M,0,c,0,L});}for(int a=0;a<t;a++)for(int b=a+1;b<t;b++){unsigned M=(1u<<(a*t+a))|(1u<<(b*t+b));P.emplace(M,Pattern{M,1,a,b,0});M|=(1u<<(a*t+b))|(1u<<(b*t+a));P.emplace(M,Pattern{M,2,a,b,0});}return P;}
Rows physical(const Rows&O,unsigned M){int t=O.size(),full=(1<<t)-1,root=2*t;Rows T(root+1);for(int i=0;i<t;i++){T[i]=O[i];T[t+i]=(full^(1<<i)^O[i])<<t;T[t+i]|=1<<root;}for(int i=0;i<t;i++)for(int j=0;j<t;j++)if(M>>(i*t+j)&1)T[i]|=1<<(t+j);else T[t+j]|=1<<i;T[root]=full;return T;}
struct Covers{int t,N;vector<vector<Z>>D;vector<Z>H;const Rows&O;Covers(const Rows&rows):t(rows.size()),N(1<<t),D(N,vector<Z>(t)),H(N),O(rows){H[0]=1;for(int i=0;i<t;i++)D[1<<i][i]=1;for(int mask=1;mask<N;mask++){for(int i=0;i<t;i++)if(D[mask][i])for(int j=0;j<t;j++)if(!(mask>>j&1)&&(O[i]>>j&1))D[mask|1<<j][j]+=D[mask][i];H[mask]=accumulate(D[mask].begin(),D[mask].end(),Z(0));}}Z F(int mask,int ends,bool empty){if(!mask)return empty;Z z=0;for(int i=0;i<t;i++)if(ends>>i&1)z+=D[mask][i];return z;}Z q(Pattern p){int X=(N-1)^(1<<p.a),K=0,J=p.leaves;for(int i=0;i<t;i++)if(O[i]>>p.a&1)K|=1<<i;if(p.kind){X^=1<<p.b;J=0;for(int i=0;i<t;i++)if(O[i]>>p.b&1)J|=1<<i;}Z z=0;for(int A=X;;A=(A-1)&X){int rem=X^A;for(int B=rem;;B=(B-1)&rem){z+=F(A,K,true)*F(B,J,p.kind!=0)*H[rem^B];if(!B)break;}if(!A)break;}return z;}};
int main(){vector<int>expected={0,0,5,21,62,160};long long controls=0,clone_controls=0,target_tests=0,first_survivors=0;map<Z,long long>target_hist;vector<array<long long,4>>summary;for(int t=1;t<=5;t++){auto P=patterns(t);check((int)P.size()==expected[t],"support pattern count");vector<pair<int,int>>edges;for(int i=0;i<t;i++)for(int j=i+1;j<t;j++)edges.push_back({i,j});long long tested=0,selected=0;for(int bits=0;bits<(1<<(int)edges.size());bits++){Rows O(t);for(int k=0;k<(int)edges.size();k++){auto[i,j]=edges[k];if(bits>>k&1)O[i]|=1<<j;else O[j]|=1<<i;}Covers C(O);for(auto [code,p]:P){tested++;Z q=C.q(p);check(q>0,"positive half cover count");if(t<=4){Rows T=physical(O,code);auto a=runs(T);check(a[2]==(p.kind==2?4:2)*q*q,"independent direct run versus square formula");check(a[0]==hp(T),"first run count");check(hp(clone(T,2*t,2))==a[0]+2*a[1],"two clone count");check(hp(clone(T,2*t,3))==a[0]+6*a[1]+6*a[2],"three clone count");controls++;clone_controls+=3;}else if(p.kind!=2&&(q==7||q==9)){selected++;target_tests++;target_hist[q]++;Z H=hp(physical(O,code));if(H==6*q*q-1)first_survivors++;}}}summary.push_back({2*t+1,(long long)P.size(),tested,selected});}check(first_survivors==0,"no order11 A98/A162 source");check(target_hist[7]==2640&&target_hist[9]==5600,"target counts");cout<<"{\n  \"status\": \"PASS\",\n  \"physical_order_rows\": [";for(size_t i=0;i<summary.size();i++){if(i)cout<<',';auto s=summary[i];cout<<'['<<s[0]<<','<<s[1]<<','<<s[2]<<','<<s[3]<<']';}cout<<"],\n  \"direct_run_square_controls\": "<<controls<<",\n  \"exact_clone_counts\": "<<clone_controls<<",\n  \"order11_target_tests\": "<<target_tests<<",\n  \"q7_tests\": "<<target_hist[7]<<",\n  \"q9_tests\": "<<target_hist[9]<<",\n  \"first_equation_survivors\": "<<first_survivors<<"\n}\n";}
